        },
        "code": {
          "text": "Chronic exertional dyspnoea, likely multifactorial"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Condition/condition-2",
      "resource": {
        "resourceType": "Condition",
        "id": "condition-2",
